#!/usr/bin/env python3
from __future__ import annotations
import argparse,json
from pathlib import Path
def fmt(v): return f"{float(v):.1f}".replace(".",",")
def main():
    ap=argparse.ArgumentParser(); ap.add_argument("--cis",default="data/cis_3584_2026.json"); ap.add_argument("--latest",default="web/data/latest.json"); ap.add_argument("--out",default="web/cis-3584-indecisos.html"); a=ap.parse_args()
    c=json.load(open(a.cis,encoding="utf-8")); l=json.load(open(a.latest,encoding="utf-8"))
    cv={r["party"]:r for r in c["vote_estimate"]}; mv={p["party"]:p for p in l.get("parties",[])}
    rows="".join(f'<tr><td><strong>{p}</strong></td><td class="num">{fmt(cv[p]["direct_pct"])}%</td><td class="num">{fmt(cv[p]["pct"])}%</td><td class="num">{fmt(float(cv[p]["pct"])-float(cv[p]["direct_pct"]))} pp</td></tr>' for p in ("PSOE","PP","VOX") if p in cv)
    # The last column is not computed; replaced below by estimate-vs-media in the article.
    comp="".join(f'<tr><td><strong>{p}</strong></td><td class="num">{fmt(cv[p]["pct"])}%</td><td class="num">{fmt(mv[p]["mean"])}%</td><td class="num">{fmt(float(cv[p]["pct"])-float(mv[p]["mean"]))} pp</td></tr>' for p in ("PSOE","PP","VOX") if p in cv and p in mv)
    title="El 18,1 % que no se pronuncia · CIS 3584 · 29N"
    desc="CIS 3584: 15,8 % no sabe y 2,3 % no contesta. Voto directo y estimación no son lo mismo. No es un pronóstico ni un bloque de indecisos."
    html=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><meta name="description" content="{desc}"><meta name="robots" content="index,follow">
<link rel="canonical" href="https://elecciones29n.pruebapublica.com/cis-3584-indecisos.html">
<meta property="og:type" content="article"><meta property="og:site_name" content="Elecciones 29N"><meta property="og:locale" content="es_ES"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="https://elecciones29n.pruebapublica.com/cis-3584-indecisos.html"><meta property="og:image" content="https://elecciones29n.pruebapublica.com/og-cis-3584-indecisos.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{title}"><meta name="twitter:description" content="{desc}"><meta name="twitter:image" content="https://elecciones29n.pruebapublica.com/og-cis-3584-indecisos.png">
<script type="application/ld+json">{{"@context":"https://schema.org","@type":"NewsArticle","headline":"El 18,1 % que no se pronuncia: qué dice y qué no el CIS 3584","description":"{desc}","datePublished":"2026-11-13T07:00:00+01:00","dateModified":"2026-11-13T07:00:00+01:00","inLanguage":"es","isAccessibleForFree":true,"author":{{"@type":"Person","name":"Miguel Castillo"}},"publisher":{{"@type":"Organization","name":"Elecciones 29N","url":"https://elecciones29n.pruebapublica.com/"}},"mainEntityOfPage":{{"@type":"WebPage","@id":"https://elecciones29n.pruebapublica.com/cis-3584-indecisos.html"}},"citation":{{"@type":"CreativeWork","name":"CIS 3584 Preelectoral elecciones generales 2026","url":"{c["source_url"]}"}}}}</script>
<style>body{{margin:0;background:#0b0c1c;color:#eef0f6;font:16px/1.6 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}}main{{max-width:860px;margin:0 auto;padding:42px 20px 60px}}a{{color:#8ec5ff}}.eyebrow{{color:#3ddc97;font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:700}}h1{{font-family:Georgia,serif;font-size:clamp(34px,6vw,58px);line-height:1.04;margin:8px 0 12px}}.lead{{font-size:19px;color:#a7abc4;max-width:64ch}}.box{{background:#12142a;border:1px solid #262a4a;border-radius:14px;padding:18px 20px;margin:22px 0}}.grid{{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}}@media(max-width:650px){{.grid{{grid-template-columns:1fr}}}}.kpi{{background:#171a34;border-radius:10px;padding:12px}}.kpi b{{display:block;font-size:30px;color:#ff5a1f}}.kpi span{{font-size:12px;color:#a7abc4}}table{{width:100%;border-collapse:collapse;font-size:14px}}th,td{{padding:8px 6px;border-bottom:1px solid #262a4a;text-align:left}}th{{color:#a7abc4;font-size:12px;text-transform:uppercase;letter-spacing:.06em}}.num{{text-align:right;font-variant-numeric:tabular-nums}}.small{{font-size:13px;color:#a7abc4}}</style></head><body><main>
<p class="eyebrow">CIS 3584 · 12-nov-2026</p><h1>El 18,1 % que no se pronuncia.</h1>
<p class="lead">El CIS 3584 no es un pronóstico. Publica voto directo sobre censo y estimación sobre voto válido; además, una parte de la muestra no se pronuncia.</p>
<div class="grid"><div class="kpi"><b>{fmt(c["no_sabe_pct"])} %</b><span>No sabe</span></div><div class="kpi"><b>{fmt(c["no_contesta_pct"])} %</b><span>No contesta</span></div></div>
<div class="box"><h2>Qué dicen los datos</h2><p><strong>45.074 entrevistas</strong>, CATI, campo <strong>7–30 octubre 2026</strong>. El CIS publica dos capas: voto directo (sobre censo) y estimación de voto (sobre voto válido). No son intercambiables.</p><table><thead><tr><th>Partido</th><th class="num">Voto directo</th><th class="num">Estimación</th><th class="num">Δ</th></tr></thead><tbody>{rows}</tbody></table><p class="small">Δ = estimación − voto directo, con denominadores distintos. No es una reasignación de indecisos demostrada.</p></div>
<div class="box"><h2>Qué no se puede decir</h2><p>Que el 18,1 % sea un bloque, que vaya a votar, que se reparta proporcionalmente o que “decida” el 29N. No hay panel ni microdatos aquí para saber su destino.</p><p>La divergencia con la media tampoco se atribuye a los indecisos: cambian campo, método, denominador y estructura de partidos.</p></div>
<div class="box"><h2>CIS vs media, como contraste</h2><table><thead><tr><th>Partido</th><th class="num">CIS</th><th class="num">Media 14 d</th><th class="num">Δ</th></tr></thead><tbody>{comp}</tbody></table><p class="small">Media: {l.get("n_polls")} sondeos · {l.get("health",{}).get("n_pollsters")} casas. Comparación descriptiva; no es una media conjunta.</p></div>
<p class="small">Fuente: <a href="{c["source_url"]}" rel="noopener">CIS 3584</a> · <a href="/data/cis-3584.json">JSON</a> · <a href="/data/cis-3584.csv">CSV</a> · <a href="/robustez.html#cis-3584">Robustez</a> · <a href="/cis-3584.html">Divergencia CIS</a>.</p>
<p class="small">No es un pronóstico. No es voto oculto. Publicado como lectura de método.</p>
</main></body></html>'''
    Path(a.out).write_text(html,encoding="utf-8"); print("ok",a.out)
if __name__=="__main__": main()
